func TestCourtTruncateMultibyte(t *testing.T) {
	// "Hello, 世界" - 10 characters total (H, e, l, l, o, ,,  , 世, 界)
	// '世' and '界' are 3 bytes each in UTF-8.
	// Let's check what base vs head does for n = 8 characters.
	s := "Hello, 世界"
	got := Truncate(s, 8)
	// Base (rune-based): len([]rune(s)) is 9. n=8 <= 9? Wait, len([]rune) = 9, so if n=8, it truncates to 8 runes: "Hello, 世" + "…"
	// Head (byte-based): len(s) is 12 bytes. If n=8, it does s[:8] + "…" which cuts off in the middle of '世'.
	t.Logf("Truncate(%q, 8) = %q", s, got)
}
